// TH16 v1.00a Stage 4 道中 wave: two rounds x 14 GirlA02.
// Source: st04.ecl.txt MainSub00:1427-1461 (entry), GirlA02/GirlA02F/GirlA02_at/GirlA02_at2
// dependencies in source.txt. The source wait(120) before the entry is the shell opening buffer.
const TIME_LIMIT: int = 1240;
const OPENING_BUFFER: int = 120;

// Transcribed bullet types (transcribe/th16/touhou-bullets.ecl aliases of the TH16 0-43 slots).
const TH16_BALL: int = 416; // source etSprite(0, 4, 6)
const TH16_RICE: int = 480; // source etSprite(1, 8, 2)

// Source GirlA02_at: aimed single-lane fan, 3-shot burst every 59 frames, 40 groups.
// etCount(0, 1, layers) pushes 1 on E/N/H and 2 on Lunatic; etSpeed(s0, 1.8).
async sub girl_ball() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var speed0: fx = 1.5fx;
    var layers: int = 1;
    if rank == RANK_NORMAL { speed0 = 2.2fx; }
    if rank == RANK_HARD { speed0 = 3.0fx; }
    if rank == RANK_LUNATIC { speed0 = 3.5fx; layers = 2; }
    var groups: int = 40; // $A = 40
    while groups > 0 {
        var burst: int = 3; // $B = 3
        while burst > 0 {
            // etAim(0, 0): aim A is resolved once per etOn (layer-independent).
            var aim: angle = aim_player();
            // etEx type 2 ANIM a=1: spawn position -= 4 * velocity.
            var r0: fx = 4fx * speed0;
            _ = fire(TH16_BALL, 6, $self_x - r0 * cos(aim), $self_y - r0 * sin(aim),
                     speed0, aim, none, none);
            if layers > 1 {
                var speed1: fx = 1.8fx; // etSpeed second endpoint
                var r1: fx = 4fx * speed1;
                _ = fire(TH16_BALL, 6, $self_x - r1 * cos(aim), $self_y - r1 * sin(aim),
                         speed1, aim, none, none);
            }
            burst = burst - 1;
            wait(3);
        }
        wait(50);
        groups = groups - 1;
    }
}

// Source GirlA02_at2: fixed 90-degree rice, one volley every 20 frames, 40 volleys.
// etCount(1, 1, layers) pushes 1 on E/N and 2 on H/L; etSpeed(s0, 2.2).
async sub girl_rice() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var speed0: fx = 1.5fx;
    var layers: int = 1;
    if rank == RANK_NORMAL { speed0 = 2.0fx; }
    if rank == RANK_HARD { speed0 = 2.4fx; layers = 2; }
    if rank == RANK_LUNATIC { speed0 = 3.0fx; layers = 2; }
    var shots: int = 40; // $A = 40
    while shots > 0 {
        // etAim(1, 1) + etAngle(1, pi/2, 0): fixed direction, no player aim.
        var dir: angle = 90deg;
        var r0: fx = 4fx * speed0; // etEx type 2 ANIM a=1 recoil
        _ = fire(TH16_RICE, 2, $self_x - r0 * cos(dir), $self_y - r0 * sin(dir),
                 speed0, dir, none, none);
        if layers > 1 {
            var speed1: fx = 2.2fx; // etSpeed second endpoint
            var r1: fx = 4fx * speed1;
            _ = fire(TH16_RICE, 2, $self_x - r1 * cos(dir), $self_y - r1 * sin(dir),
                     speed1, dir, none, none);
        }
        wait(20);
        shots = shots - 1;
    }
}

// Source GirlA02 -> GirlA02F: hurtbox/hitbox, two async firing branches, three-stage move.
// mirror = source child mirror flag from enmCreateM (1) vs enmCreate (0). The mirror flips
// the horizontal component of movement angles: 45deg -> 135deg, 0deg -> 180deg.
async sub girl_a02(mirror: int) {
    set_invuln(65535);
    set_hitbox(8fx);   // setHitbox(16.0f, 16.0f) -> radius 8
    set_hurtbox(12fx); // setHurtbox(24.0f, 24.0f) -> radius 12
    spawn girl_ball();
    spawn girl_rice();
    var a2: angle = 45deg;
    var a3: angle = 0deg;
    if mirror != 0 {
        a2 = 135deg;
        a3 = 180deg;
    }
    move_vel(0, 90deg, 0.5fx, EASE_LINEAR);  // moveVel(1.5707964f, 0.5f)
    wait(60);
    move_vel(60, a2, 1.5fx, EASE_LINEAR);    // moveVelTime(60, 0, 0.7853982f, 1.5f)
    wait(60);
    move_vel(60, a3, 2.5fx, EASE_LINEAR);    // moveVelTime(60, 0, 0.0f, 2.5f)
    wait(60);
    loop { wait(1000); } // source GirlA02F wait(1000) loop: the enemy stays until it is recycled
}

// Source MainSub00:1427-1461 entry: $C = 2, then 14 enmCreate/enmCreateM pairs with wait(20).
sub stage_wave() {
    var rounds: int = 2; // $C = 2
    while rounds > 0 {
        _ = spawn_enemy(-128fx, 64fx, 200, 0, 0, 0, girl_a02(0));
        wait(20); // wait($A), $A = 20 from the entry context
        _ = spawn_enemy(128fx, 64fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        _ = spawn_enemy(-32fx, 80fx, 200, 0, 0, 0, girl_a02(0));
        wait(20);
        _ = spawn_enemy(32fx, 80fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        _ = spawn_enemy(-64fx, 90fx, 200, 0, 0, 0, girl_a02(0));
        wait(20);
        _ = spawn_enemy(64fx, 90fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        _ = spawn_enemy(-192fx, 64fx, 200, 0, 0, 0, girl_a02(0));
        wait(20);
        _ = spawn_enemy(192fx, 64fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        _ = spawn_enemy(-160fx, 80fx, 200, 0, 0, 0, girl_a02(0));
        wait(20);
        _ = spawn_enemy(160fx, 80fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        _ = spawn_enemy(-128fx, 90fx, 200, 0, 0, 0, girl_a02(0));
        wait(20);
        _ = spawn_enemy(128fx, 90fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        _ = spawn_enemy(-32fx, 30fx, 200, 0, 0, 0, girl_a02(0));
        wait(20);
        _ = spawn_enemy(32fx, 30fx, 200, 0, 0, 0, girl_a02(1));
        wait(20);
        rounds = rounds - 1;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    stage_wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
